css:
.ovt-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ovt-root,.ovt-root *,.ovt-root *::before,.ovt-root *::after{box-sizing:border-box}
.ovt-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ovt-root img{display:block;border:0;max-width:none}
.ovt-root > [data-node-id]{will-change:transform}
.ovt-root [hidden]{display:none!important}
.ovt-root [data-sh-theme="light"]{display:none!important}
.ovt-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.ovt-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.ovt-root .n58_8348{position:absolute;display:contents;inset:9.26% 15.46% 86.29% 64.43%}
.ovt-root .n58_8349{position:absolute;inset:9.26% 15.46% 86.29% 64.43%}
.ovt-root .x120{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.ovt-root .n58_8350{word-break:break-word;position:absolute;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:540;inset:10.37% 22.24% 87.41% 71.2%;line-height:24px;font-style:normal;color:var(--wa-text, #f8f8f8);font-size:20px;text-align:center;white-space:nowrap;width:126px}
.ovt-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.ovt-root[data-theme="light"] [data-name="Badge/Critical"] p,.ovt-root[data-theme="light"] [data-name^="status-critical"] p,.ovt-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.ovt-root[data-theme="light"] [data-name="Badge/Major"] p,.ovt-root[data-theme="light"] [data-name^="status-major"] p,.ovt-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.ovt-root[data-theme="light"] [data-name="Badge/Minor"] p,.ovt-root[data-theme="light"] [data-name^="status-minor"] p,.ovt-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.ovt-root[data-theme="light"] [data-name="Badge/Warning"] p,.ovt-root[data-theme="light"] [data-name^="status-warning"] p,.ovt-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.ovt-root[data-theme="light"] [data-name="Badge/Normal"] p,.ovt-root[data-theme="light"] [data-name^="status-normal"] p,.ovt-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.ovt-root[data-theme="light"] [data-name="Button/Ack"] p,.ovt-root[data-theme="light"] [data-name="Button/Ack All"] p,.ovt-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.ovt-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.ovt-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.ovt-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.ovt-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.ovt-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.ovt-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.ovt-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.ovt-root[data-theme="light"] :is([data-name="Symbol"],[data-name="Floor"],[data-name="Floor Layer"],[data-name="Effect"]) img{filter:brightness(1.75) saturate(.55);opacity:.7}
.ovt-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.ovt-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.ovt-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1e86f0)!important}
.ovt-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.ovt-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.ovt-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.ovt-root[data-theme="light"] :is([data-name^="Node/"],[data-name="Icons"],[data-name="Node Group"]) p{text-shadow:0 0 3px #fff,0 0 6px #fff,0 0 10px rgba(255,255,255,.9)}
.ovt-root[data-theme="light"] .n58_8350{color:var(--wa-text, #141517)}
